# %% [markdown]
# # NASA almond monostatic RCS study
#
# Reproducible study of the monostatic RCS of the EMCC/NASA PEC almond
# (length 9.936 in) at 1.19 GHz using Palace plane wave excitation, including a
# mesh resolution study. The almond mesh is generated by
# `tools/rcs/almond_mesh.py` (lofted elliptical cross sections with conformal
# tip caps and a spherical absorbing boundary).
#
# Reference data: digitize the Woo et al. (1993) 1.19 GHz measured VV/HH curves
# (or use the Austin RCS Benchmark Suite, CC-BY-SA-4.0) into a CSV with columns
# `phi_deg, sigma_vv_dBsm, sigma_hh_dBsm` and point `REFERENCE_CSV` at it. The
# comparison cell is skipped if the file is missing.
#
# This file is in jupytext percent format: run it directly or convert with
# `jupytext --to ipynb almond_rcs_study.py`. Set `RUN_PALACE=1` to generate the
# meshes and run the sweeps (expensive); otherwise existing outputs are parsed.

# %%
import os
import subprocess
import sys
from pathlib import Path

import numpy as np
import matplotlib
import matplotlib.pyplot as plt

matplotlib.rcParams.update({"figure.dpi": 110, "font.size": 10})

TOOLS = Path(__file__).resolve().parents[1] if "__file__" in globals() else Path(
    "/home/luis/palace/tools/rcs")
sys.path.insert(0, str(TOOLS))

PALACE = os.environ.get("PALACE_BIN", "/home/luis/palace/build/bin/palace")
WORKDIR = Path(os.environ.get("RCS_WORKDIR", "./almond_work")).resolve()
FIGDIR = WORKDIR / "figures"
RUN_PALACE = os.environ.get("RUN_PALACE", "0") == "1"
NPROC = int(os.environ.get("RCS_NPROC", "8"))
FREQ_GHZ = 1.19
OUTER_RADIUS = 0.8
REFERENCE_CSV = Path(os.environ.get("RCS_ALMOND_REFERENCE", WORKDIR / "woo_119.csv"))
WORKDIR.mkdir(parents=True, exist_ok=True)
FIGDIR.mkdir(parents=True, exist_ok=True)

# Resolution levels: (name, h_tip/h_surface, h_far).
RESOLUTIONS = {
    "L1": (0.015, 0.050),
    "L2": (0.009, 0.035),
    "L3": (0.005, 0.022),
}
AZIMUTHS = [0.0, 90.0, 180.0]  # monostatic sweep subset (tip, broadside, tail)


def make_config(case, mesh):
    import json
    import math
    waves = []
    idx = 1
    for phi_deg in AZIMUTHS:
        phi = math.radians(phi_deg)
        k = [math.cos(phi), math.sin(phi), 0.0]
        hh = [-math.sin(phi), math.cos(phi), 0.0]
        for pol in ([0.0, 0.0, 1.0], hh):  # VV, HH
            waves.append({"Index": idx, "Attributes": [1], "Excitation": idx,
                          "Direction": k, "Polarization": pol, "Amplitude": 1.0})
            idx += 1
    cfg = {
        "Problem": {"Type": "Driven", "Verbose": 1, "Output": f"postpro/{case}"},
        "Model": {"Mesh": mesh, "L0": 1.0},
        "Domains": {"Materials": [{"Attributes": [1]}]},
        "Boundaries": {
            "PEC": {"Attributes": [2]},
            "Absorbing": {"Attributes": [1], "Order": 2},
            "PlaneWave": waves,
            "Postprocessing": {"FarField": {"Attributes": [1], "ThetaPhis": [[90, 0]],
                                            "Scattered": True, "Monostatic": True}},
        },
        "Solver": {"Order": 2, "Driven": {"Samples": [{"Type": "Point",
                                                       "Freq": [FREQ_GHZ]}]}},
    }
    (WORKDIR / f"{case}.json").write_text(json.dumps(cfg, indent=1))


# %% [markdown]
# ## Run the resolution study (optional)

# %%
if RUN_PALACE:
    for case, (hmin, hmax) in RESOLUTIONS.items():
        subprocess.run([sys.executable, str(TOOLS / "almond_mesh.py"), f"{case}.msh",
                        str(OUTER_RADIUS), str(hmin), str(hmax)],
                       cwd=WORKDIR, check=True)
        make_config(case, f"{case}.msh")
        subprocess.run([PALACE, "-np", str(NPROC), f"{case}.json"], cwd=WORKDIR,
                       check=True)

# %% [markdown]
# ## Monostatic RCS per resolution
#
# Each plane wave excitation writes a monostatic row in `farfield-rcs.csv`
# (theta=90, phi=180 for the backscatter direction). Excitations alternate VV
# and HH for each azimuth.

# %%
def read_monostatic(case):
    import csv
    path = WORKDIR / "postpro" / case / "farfield-rcs.csv"
    if not path.exists():
        return None
    out = {}
    with open(path) as f:
        reader = csv.reader(f)
        header = [h.strip() for h in next(reader)]
        ip = next(i for i, h in enumerate(header) if h.startswith("phi"))
        idb = next(i for i, h in enumerate(header) if h.startswith("RCS (dBsm)"))
        rows = [(float(r[ip]), float(r[idb])) for r in reader]
    # Excitations are (VV, HH) pairs for each azimuth, in AZIMUTHS order.
    for i, phi in enumerate(AZIMUTHS):
        out[phi] = {"VV": rows[2 * i][1], "HH": rows[2 * i + 1][1]}
    return out


results = {case: read_monostatic(case) for case in RESOLUTIONS}
print(f"{'case':>4} {'phi':>5} {'VV dBsm':>9} {'HH dBsm':>9}")
for case, res in results.items():
    if res is None:
        continue
    for phi in AZIMUTHS:
        print(f"{case:>4} {phi:5.0f} {res[phi]['VV']:9.2f} {res[phi]['HH']:9.2f}")

# %% [markdown]
# ## Convergence and reference comparison

# %%
fig, axes = plt.subplots(1, 2, figsize=(11, 4.5), sharey=True)
for ax, pol in zip(axes, ("VV", "HH")):
    for case, res in results.items():
        if res is None:
            continue
        ax.plot([r[0] for r in [AZIMUTHS]], [res[p][pol] for p in AZIMUTHS],
                marker="o", label=f"Palace {case}")
    if REFERENCE_CSV.exists():
        ref = np.genfromtxt(REFERENCE_CSV, delimiter=",", names=True,
                            encoding="utf-8")
        col = "sigma_vv_dBsm" if pol == "VV" else "sigma_hh_dBsm"
        ax.plot(ref["phi_deg"], ref[col], "k--", lw=1.2, label="Woo et al. (1993)")
    ax.set_title(f"{pol} polarization")
    ax.set_xlabel("azimuth (deg.)")
    ax.set_ylabel("monostatic RCS (dBsm)")
    ax.grid(alpha=0.3)
    ax.legend(fontsize=8)
fig.suptitle(f"NASA almond monostatic RCS at {FREQ_GHZ} GHz")
fig.tight_layout()
fig.savefig(FIGDIR / "almond_monostatic_convergence.png")
print(f"Wrote {FIGDIR / 'almond_monostatic_convergence.png'}")

